284	impl Eval for ast::Dict<'_> {
285	    type Output = Dict;
286	
287	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
288	        let mut map = indexmap::IndexMap::default();
289	        let mut invalid_keys = eco_vec![];
290	
291	        for item in self.items() {
292	            match item {
293	                ast::DictItem::Named(named) => {
294	                    map.insert(named.name().get().clone().into(), named.expr().eval(vm)?);
295	                }
296	                ast::DictItem::Keyed(keyed) => {
297	                    let raw_key = keyed.key();
298	                    let key = raw_key.eval(vm)?;
299	                    let key =
300	                        key.cast::<Str>().at(raw_key.span()).unwrap_or_else(|errors| {
301	                            invalid_keys.extend(errors);
302	                            Str::default()
303	                        });
304	                    map.insert(key, keyed.expr().eval(vm)?);
305	                }
306	                ast::DictItem::Spread(spread) => match spread.expr().eval(vm)? {
307	                    Value::None => {}
308	                    Value::Dict(dict) => map.extend(dict),
309	                    v => bail!(spread.span(), "cannot spread {} into dictionary", v.ty()),
310	                },
311	            }
312	        }
313	
314	        if !invalid_keys.is_empty() {
315	            return Err(invalid_keys);
316	        }
317	
318	        Ok(map.into())
319	    }
320	}
