500	/// Find invalid digits for a non-decimal integer. Returns the sub-range of the
501	/// digits and a string separated by commas.
502	///
503	/// We only check for digits/letters depending on the base since the lexer
504	/// allows only ASCII digits for binary/octal, but allows ASCII letters for hex.
505	pub fn find_bad_digits(
506	    base: ast::NonDecimalBase,
507	    digits: &str,
